                        // EXA5, EXAF - Skip if key not pressed (variations)
                        else if (opCode >= 0xEA00 && opCode <= 0xEAFF) {
                            const x = (opCode >> 8) & 0x0F;
                            const n = opCode & 0x00FF;
                            if (this.keysPressed.has(n)) {
                                this.programCounter += 2;
                            }
                        }

                        break;

                    case (opCode & 0xF000 === 0xFF00):
                        // FFO9 - Return from subroutine
                        if (opCode === 0xFFE9) {
                            this.stackPointer--;
                            this.programCounter = this.stack[this.stackPointer];
                        }

                        // FF15 - Set DY to VX
                        else if (opCode === 0xFF15) {
                            const x = (opCode >> 8) & 0x0F;
                            const delayTimer = this.registers[x];
                        }

                        // FF16 - Set SY to VX
                        else if (opCode === 0xFF16) {
                            const x = (opCode >> 8) & 0x0F;
                            const soundTimer = this.registers[x];
                        }

                        // FF17 - Set SX to VX
                        else if (opCode === 0xFF17) {
                            const x = (opCode >> 8) & 0x0F;
                            const delayTimer = this.registers[x] + 64;
                        }

                        // FF1E - Add VX to IX
                        else if (opCode === 0xFF1E) {
                            const x = (opCode >> 8) & 0x0F;
                            this.indexRegister += this.registers[x];
                        }

                        // FF29 - Set IX to location of sprite for digit VX
                        else if (opCode === 0xFF29) {
                            const x = (opCode >> 8) & 0x0F;
                            const n = this.registers[x] % 10;
                            this.indexRegister = 0x50 + n * 5;
                        }

                        // FF43 - Set IX to BCD of VX
                        else if (opCode === 0xFF43) {
                            const x = (opCode >> 8) & 0x0F;
                            let bcd = this.registers[x];
                            bcd += Math.floor(bcd / 100) * 100;
                            bcd += Math.floor((bcd % 100) / 10) * 10;
                            bcd += bcd % 10;
                            this.indexRegister = bcd;
                        }

                        // FF65 - Store V0-VF in IX
                        else if (opCode === 0xFF65) {
                            const x = (opCode >> 8) & 0x0F;
                            for (let i = 0; i < 16; i++) {
                                this.memory[this.indexRegister + i] = this.registers[i];
                            }
                        }

                        // FF66 - Store IX into V0-VF
                        else if (opCode === 0xFF66) {
                            const x = (opCode >> 8) & 0x0F;
                            for (let i = 0; i < 16; i++) {
                                this.registers[i] = this.memory[this.indexRegister + i];
                            }
                        }

                        // FF75 - Load V0-VF from IX
                        else if (opCode === 0xFF75) {
                            const x = (opCode >> 8) & 0x0F;
                            for (let i = 0; i < 16; i++) {
                                this.registers[i] = this.memory[this.indexRegister + i];
                            }
                        }

                        // FF76 - Store VX in delay timer
                        else if (opCode === 0xFF76) {
                            const x = (opCode >> 8) & 0x0F;
                            this.delayTimer = this.registers[x];
                        }

                        // FF77 - Store VX in sound timer
                        else if (opCode === 0xFF77) {
                            const x = (opCode >> 8) & 0x0F;
                            this.soundTimer = this.registers[x];
                        }

                        break;

                    default:
                        // Unknown instruction, skip
                        this.programCounter += 2;
                        break;
                }

                return true;
            }

            // Main loop
            run() {
                if (this.running) return;

                this.running = true;

                const speedRange = document.getElementById('speedRange');
                const speedValue = parseInt(speedRange.value);
                const framesPerSecond = Math.round(60 * (100 / speedValue));

                let lastTime = performance.now();

                const loop = () => {
                    if (!this.running) return;

                    const now = performance.now();
                    const elapsed = now - lastTime;

                    if (elapsed >= 1000 / framesPerSecond) {
                        lastTime = now;

                        // Execute instruction
                        this.executeInstruction();

                        // Handle timers at 60 Hz
                        this.delayTimer--;
                        this.soundTimer--;

                        if (this.drawFlag) {
                            this.drawFlag = false;
                            this.draw();
                        }

                        // Update UI
                        this.updateDebugPanel();
                    }

                    requestAnimationFrame(loop);
                };

                requestAnimationFrame(loop);
            }

            pause() {
                this.running = false;
            }

            step() {
                if (!this.running) {
                    this.executeInstruction();
                    this.draw();
                    this.updateDebugPanel();
                }
            }

            reset() {
                this.pause();
                this.keysPressed.clear();

                // Clear screen
                for (let i = 0; i < this.display.length; i++) {
                    this.display[i] = 0;
                }
                this.draw();

                // Reset registers and timers
                this.registers.fill(0);
                this.indexRegister = 0x000;
                this.programCounter = 0x200;
                this.delayTimer = 0;
                this.soundTimer = 0;
                this.stackPointer = 0;
                this.drawFlag = false;
                this.vf = 0xFF;

                // Reset memory to font set
                for (let i = 0; i < this.fontset.length; i++) {
                    this.memory[i] = this.fontset[i];
                }

                this.updateDebugPanel();
                document.getElementById('statusBar').textContent = 'Emulator reset. Ready.';
            }

            // Load ROM from file input
            loadROMFromFile(input) {
                const file = input.files[0];
                if (!file) return;

                const reader = new FileReader();
                reader.onload = (e) => {
                    const data = e.target.result;

                    try {
                        // Convert string to Uint8Array
                        const romBytes = [];
                        for (let i = 0; i < data.length; i++) {
                            romBytes.push(parseInt(data.charCodeAt(i), 16));
                        }

                        // Copy ROM to memory at 0x200
                        const startAddr = 0x200;
                        let byteIndex = 0;
                        while (byteIndex + startAddr < this.memory.length) {
                            if (byteIndex < romBytes.length) {
                                this.memory[startAddr + byteIndex] = romBytes[byteIndex];
                                byteIndex++;
                            } else {
                                break;
                            }
                        }

                        this.reset();
                        this.programCounter = startAddr;
                        this.draw();
                        this.updateDebugPanel();
                        document.getElementById('statusBar').textContent = 'ROM loaded successfully!';
                    } catch (err) {
                        document.getElementById('statusBar').textContent = 'Error loading ROM: ' + err.message;
                    }
                };

                reader.readAsText(file);
            }

            // Handle key press/release events
            keyPress(key, pressed) {
                this.setKey(key, pressed);

                const btn = document.querySelector(`.key-btn[data-key="${key}"]`);
                if (btn) {
                    if (pressed) {
                        btn.classList.add('active');
                    } else {
                        btn.classList.remove('active');
                    }
                }

                this.updateDebugPanel();
            }

            updateDebugPanel() {
                // Update registers display
                const regGrid = document.getElementById('registersGrid');
                let gridHTML = '';

                for (let i = 0; i < 16; i++) {
                    gridHTML += `<div class="reg-item">V${i}: <span class="reg-value">${this.registers[i].toString(16).toUpperCase().padStart(2, '0')}</span></div>`;
                }

                regGrid.innerHTML = gridHTML;

                // Update PC and IX displays
                document.getElementById('pcDisplay').textContent = this.programCounter.toString(16).toUpperCase().padStart(3, '0');
                document.getElementById('indexDisplay').textContent = this.indexRegister.toString(16).toUpperCase().padStart(3, '0');

                // Update stack display
                let stackHTML = '';
                for (let i = 0; i < this.stackPointer; i++) {
                    stackHTML += `<div>${this.stack[i].toString(16).toUpperCase().padStart(2, '0')}</div>`;
                }
                document.getElementById('stackDisplay').innerHTML = stackHTML || '<div>(empty)</div>';

                // Decode and display current instruction
                const opCode = this.memory[this.programCounter] << 8 | this.memory[this.programCounter + 1];
                const instructionText = this.decodeInstruction(opCode);
                document.getElementById('instructionDisplay').textContent = instructionText || `Unknown: ${opCode.toString(16).toUpperCase().padStart(4, '0')}`;
            }

            decodeInstruction(opCode) {
                const nnn = opCode & 0x0FFF;
                const x = (opCode >> 8) & 0x0F;
                const y = (opCode >> 4) & 0x0F;
                const nn = opCode & 0x00FF;
                const n = opCode & 0x000F;

                switch (true) {
                    case (opCode === 0x00E0): return '00E0: Clear screen';
                    case (opCode === 0x0EE1): return `0EE${n.toString(16).padStart(2, '0')}: Return from subroutine`;
                    case (opCode >= 0x1000 && opCode <= 0x1FFF): return `1NNN: Jump to address ${nnn.toString(16)}`;
                    case (opCode >= 0x2000 && opCode <= 0x2FFF): return `2NNN: Call subroutine at ${nnn.toString(16)}`;
                    case (opCode >= 0x3000 && opCode <= 0x3FFF): return `3XNN: Skip if V${x} ≠ ${nn.toString(16)}`;
                    case (opCode >= 0x4000 && opCode <= 0x4FFF): return `4XNN: Skip if V${x} = ${nn.toString(16)}`;
                    case (opCode >= 0x5000 && opCode <= 0x50FF): return `5XY0: Skip if V${x} ≠ V${y}`;
                    case (opCode >= 0x6000 && opCode <= 0x6FFF): return `6XNN: Set V${x} = ${nn.toString(16)}`;
                    case (opCode >= 0x7000 && opCode <= 0x7FFF): return `7XNN: Add ${nn.toString(16)} to V${x}`;
                    case (opCode >= 0x8000 && opCode <= 0x80FF): return `8XY0: Set V${x} = V${y}`;
                    case (opCode >= 0x8100 && opCode <= 0x81FF): return `8XY1: Set V${x} = V${x} OR V${y}`;
                    case (opCode >= 0x8200 && opCode <= 0x82FF): return `8XY2: Set V${x} = V${x} AND V${y}`;
                    case (opCode >= 0x8300 && opCode <= 0x83FF): return `8XY3: Set V${x} = V${x} XOR V${y}`;
                    case (opCode >= 0x8400 && opCode <= 0x84FF): return `8XY4: Add V${y} to V${x}, VF = carry`;
                    case (opCode >= 0x8500 && opCode <= 0x85FF): return `8XY5: Subtract V${y} from V${x}, VF = borrow`;
                    case (opCode >= 0x8600 && opCode <= 0x86FF): return `8XY6: Shift V${x} right, VF = LSB`;
                    case (opCode >= 0x8700 && opCode <= 0x87FF): return `8XY7: Add V${y} to V${x}, VF = borrow`;
                    case (opCode >= 0x8E00 && opCode <= 0x8EFF): return `8XYE: Shift V${x} left, VF = MSB`;
                    case (opCode >= 0x9000 && opCode <= 0x90FF): return `9XY0: Skip if V${x} = V${y}`;
                    case (opCode >= 0xA000 && opCode <= 0xAFFF): return `ANNN: Set IX = ${nnn.toString(16)}`;
                    case (opCode >= 0xB000 && opCode <= 0xBFFF): return `BNNN: Jump to ${nnn.toString(16)} + V${x}`;
                    case (opCode >= 0xC000 && opCode <= 0xCFFF): return `CXNN: V${x} = V${x} × ${nn.toString(16)}`;
                    case (opCode >= 0xD000 && opCode <= 0xDFFF): return `DXYN: Draw sprite at V${x},V${y} height ${n}`;
                    case (opCode >= 0xE000 && opCode <= 0xE1FF): return `EX9E/EXA1: Key test for V${x}`;
                    case (opCode === 0xFFE9): return 'FFE9: Return from subroutine';
                    case (opCode === 0xFF15): return 'FF15: Set delay timer to V${x}';
                    case (opCode === 0xFF16): return 'FF16: Set sound timer to V${x}';
                    case (opCode === 0xFF17): return 'FF17: Set delay timer to V${x} + $40';
                    case (opCode === 0xFF1E): return 'FF1E: Add V${x} to IX';
                    case (opCode === 0xFF29): return `FF29: Set IX to sprite for digit ${this.registers[x] % 10}`;
                    case (opCode === 0xFF43): return 'FF43: Set IX to BCD of V${x}';
                    case (opCode === 0xFF65): return `FF65: Store V0-VF in memory at IX`;
                    case (opCode === 0xFF66): return `FF66: Load V0-VF from memory at IX`;
                    case (opCode === 0xFF75): return 'FF75: Load V0-VF from IX';
                    case (opCode === 0xFF76): return 'FF76: Store V${x} in delay timer';
                    case (opCode === 0xFF77): return 'FF77: Store V${x} in sound timer';
                    default: return `Unknown: ${opCode.toString(16).toUpperCase().padStart(4, '0')}`;
                }
            }

            // Start with demo program
            init() {
                this.loadFontSet();
                this.reset();

                // Demo program: draws a simple sprite and waits for key press
                // This is a "hello world" CHIP-8 program

                const demo = [
                    // Clear screen
                    0x0, 0xE0,

                    // Set V0 to 1 (first digit) - will draw at x=0, y=0
                    0x6, 0, 0x1,

                    // Move index register to start of font set
                    0xA, 0, 0x50,

                    // Draw sprite at V0=0 (x=0), V2=0 (y=0), height 5
                    0xD, 0, 2, 0, 0, 0x5,

                    // Wait for key press (key A = 0xA)
                    0xE, 0xA, 0x9E,

                    // Return from subroutine (infinite loop)
                    0xFF, 0xE9
                ];

                // Copy demo to memory starting at 0x200
                let addr = 0x200;
                for (let i = 0; i < demo.length && addr + 1 < this.memory.length; i += 2) {
                    this.memory[addr++] = demo[i];
                    this.memory[addr++] = demo[i + 1];
                }

                this.programCounter = 0x200;
            }
        }

        // Initialize emulator
        const emulator = new Chip8();
        emulator.init();

        // Handle keyboard events
        document.addEventListener('keydown', (e) => {
            emulator.handleKeyboard(e.key);
            emulator.keyPress(emulator.mapKeyToChip8(e.key), true);
        });

        document.addEventListener('keyup', (e) => {
            emulator.keyPress(emulator.mapKeyToChip8(e.key), false);
        });

        // Keyboard mapping helper
        Chip8.prototype.mapKeyToChip8 = function(keyCode) {
            const keyMap = {
                '1': 0x1, '2': 0x2, '3': 0x3, '4': 0x4,
                'q': 0x5, 'w': 0x6, 'e': 0x7, 'r': 0x8,
                'a': 0x9, 's': 0xa, 'd': 0xb, 'f': 0xc,
                'z': 0xd, 'x': 0xe, 'c': 0xf, 'v': 0x0
            };

            if (keyMap[keyCode] !== undefined) {
                return keyMap[keyCode];
            }

            // Numeric keypad
            if (keyCode >= 48 && keyCode <= 57) {
                return 0x1 + Math.floor((keyCode - 48) / 5);
            }

            // Arrow keys
            const arrowMap = {
                'ArrowUp': 0x1,
                'ArrowRight': 0x2,
                'ArrowDown': 0x3,
                'ArrowLeft': 0x4
            };

            return arrowMap[keyCode] || 0x0;
        };

        // Speed control
        document.getElementById('speedRange').addEventListener('input', (e) => {
            document.getElementById('speedValue').textContent = e.target.value;
        });
    </script>
</body>
